    50	const FRAME_MS: u64 = 16;
    51	
    52	fn banner_lines(fade_step: usize) -> Vec<Line<'static>> {
    53	    let palette = if fade_step == 0 {
    54	        OCEAN_GRADIENT
    55	    } else {
    56	        let idx = (fade_step - 1).min(FADE_GRADIENT.len() - 1);
    57	        std::slice::from_ref(&FADE_GRADIENT[idx])
    58	    };
    59	    BANNER
    60	        .iter()
    61	        .enumerate()
    62	        .map(|(i, raw)| {
    63	            let color = palette[i * palette.len() / BANNER.len()];
    64	            Line::from(Span::styled((*raw).to_string(), Style::default().fg(color)))
    65	        })
    66	        .collect()
    67	}
    68	
    69	fn banner_width() -> u16 {
    70	    BANNER.iter().map(|l| l.len()).max().unwrap_or(0) as u16
    71	}
