    73	pub fn play<B: Backend>(terminal: &mut Terminal<B>) -> io::Result<()> {
    74	    let banner_h = BANNER.len() as u16;
    75	    let banner_w = banner_width();
    76	
    77	    let start = Instant::now();
    78	    let hold = Duration::from_millis(HOLD_MS);
    79	    let slide = Duration::from_millis(SLIDE_MS);
    80	    let total = hold + slide;
    81	    let frame = Duration::from_millis(FRAME_MS);
    82	
    83	    loop {
    84	        if event::poll(Duration::from_millis(0))? {
    85	            if let Ok(Event::Key(_)) = event::read() {
    86	                break;
    87	            }
    88	        }
    89	
    90	        let elapsed = start.elapsed();
    91	        if elapsed >= total {
    92	            break;
    93	        }
    94	
    95	        terminal.draw(|f| {
    96	            let area = f.area();
    97	            if area.width < banner_w || area.height < banner_h {
    98	                return;
    99	            }
   100	
   101	            let center_y = area.height.saturating_sub(banner_h) / 2;
   102	
   103	            let (y, fade_step) = if elapsed < hold {
   104	                (center_y, 0usize)
   105	            } else {
   106	                let t = (elapsed - hold).as_secs_f32() / slide.as_secs_f32();
   107	                let eased = t * t;
   108	                let travel = center_y as f32 * eased;
   109	                let y = (center_y as f32 - travel).max(0.0) as u16;
   110	                let step = (eased * (FADE_GRADIENT.len() as f32)).floor() as usize + 1;
   111	                (y, step.min(FADE_GRADIENT.len()))
   112	            };
   113	
   114	            let x = area.width.saturating_sub(banner_w) / 2;
   115	            let rect = Rect::new(x, y, banner_w, banner_h);
   116	
   117	            let para = Paragraph::new(banner_lines(fade_step)).alignment(Alignment::Left);
   118	            f.render_widget(para, rect);
   119	        })?;
   120	
   121	        std::thread::sleep(frame);
   122	    }
   123	
   124	    Ok(())
   125	}

