4013	/// Sanitize one terminal row and clamp it by display cells, reserving an
4014	/// ellipsis where it fits. Paths and transcript-derived titles are untrusted
4015	/// terminal text even when they originated on the local filesystem.
4016	fn truncate_cells(raw: &str, max_width: usize) -> String {
4017	    let clean = sanitize_line(raw);
4018	    if UnicodeWidthStr::width(clean.as_str()) <= max_width {
4019	        return clean;
4020	    }
4021	    if max_width == 0 {
4022	        return String::new();
4023	    }
4024	
4025	    let ellipsis = g("…", "...");
4026	    let ellipsis_width = UnicodeWidthStr::width(ellipsis);
4027	    let (limit, suffix) = if ellipsis_width <= max_width {
4028	        (max_width - ellipsis_width, ellipsis)
4029	    } else {
4030	        (max_width, "")
4031	    };
4032	    let mut out = String::new();
4033	    let mut width = 0usize;
4034	    for ch in clean.chars() {
4035	        let ch_width = ch.width().unwrap_or(0);
4036	        if width + ch_width > limit {
4037	            break;
4038	        }
4039	        out.push(ch);
4040	        width += ch_width;
4041	    }
4042	    out.push_str(suffix);
4043	    out
4044	}
