   112	/// Width of the two-space separator between rendered segments (plain ASCII —
   113	/// no decorative interpuncts on UI surfaces).
   114	const SEP_W: usize = 2;
   115	
   116	/// Build the ordered segment list, clipping to `max_width` display columns.
   117	/// LAYOUT order: model · branch · health · error · activity · tok/s.
   118	/// SURVIVAL is separate: on overflow whole segments drop by rank — tok/s
   119	/// first, then activity, then branch, then health/error; the model (identity,
   120	/// rank 0) never drops. Whatever survives alone is width-clamped so a single
   121	/// long name can't overflow the row.
   122	pub fn segments(d: &StatusData, max_width: usize) -> Vec<Segment> {
   123	    // (segment, drop_rank) — higher rank drops first; ties drop rightmost.
   124	    let mut ranked: Vec<(Segment, u8)> = Vec::new();
   125	    if let Some(m) = d.model {
   126	        ranked.push((Segment::new(m.to_string(), Tone::Primary), 0));
   127	    }
   128	    if let Some(g) = d.git {
   129	        if let Some(seg) = git_segment(g) {
   130	            ranked.push((seg, 2));
   131	        }
   132	    }
   133	    if let Some(h) = d.health {
   134	        ranked.push((Segment::new(h.to_string(), Tone::Warn), 1));
   135	    }
   136	    if let Some(e) = d.error.filter(|e| !e.trim().is_empty()) {
   137	        ranked.push((Segment::new(e.to_string(), Tone::Warn), 1));
   138	    }
   139	    if let Some(a) = d.activity {
   140	        ranked.push((Segment::new(a.to_string(), Tone::Muted), 3));
   141	    }
   142	    if let Some(t) = d.tok_per_s {
   143	        ranked.push((Segment::new(format!("{t:.0} tok/s"), Tone::Muted), 4));
   144	    }
   145	    while ranked.len() > 1 && ranked_row_width(&ranked) > max_width {
   146	        let idx = ranked
   147	            .iter()
   148	            .enumerate()
   149	            .max_by_key(|(i, (_, rank))| (*rank, *i))
   150	            .map(|(i, _)| i)
   151	            .expect("non-empty");
   152	        ranked.remove(idx);
   153	    }
   154	    let mut out: Vec<Segment> = ranked.into_iter().map(|(s, _)| s).collect();
   155	    if let [only] = out.as_mut_slice() {
   156	        let budget = max_width.saturating_sub(1); // leading pad space
   157	        if only.text.width() > budget {
   158	            only.text = truncate_cells(&only.text, budget);
   159	        }
   160	    }
   161	    out
   162	}
   163	
   164	/// [`row_width`] over the ranked working list.
   165	fn ranked_row_width(segs: &[(Segment, u8)]) -> usize {
   166	    let text: usize = segs.iter().map(|(s, _)| s.text.width()).sum();
   167	    text + segs.len().saturating_sub(1) * SEP_W + 1
   168	}
