   190	        return None;
     1	//! CTRL's panel chrome, extracted as a reusable frame so every pane in the
     2	//! shell wears the same skin: a slate bed, a plain TITLE row (with optional
     3	//! right-aligned plain state text, e.g. the editor's `unsaved`), and a
     4	//! hairline underline. Returns the inner body rect.
     5	//!
     6	//! This is the depth-fill framing from CTRL's panel_sessions.rs, generalized —
     7	//! minus the decorative title glyph and pill styling (house rules: no
     8	//! decorative icons, plain undecorated labels).
     9	
    10	use ratatui::{
    11	    layout::Rect,
    12	    style::{Modifier, Style},
    13	    text::{Line, Span},
    14	    widgets::{Block, Paragraph},
    15	    Frame,
    16	};
    17	use unicode_segmentation::UnicodeSegmentation;
    18	use unicode_width::UnicodeWidthStr;
