    21	
    22	/// Draw the chrome for one panel and return the inner body area (below the
    23	/// title + hairline, inside the edge columns). `focused` lights the title;
    24	/// `state` renders right-aligned on the title row as plain contextual text
    25	/// (exceptional state only, e.g. the editor's `unsaved`).
    26	pub fn draw(f: &mut Frame, area: Rect, title: &str, state: Option<&str>, focused: bool) -> Rect {
    27	    if area.width < 6 || area.height < 4 {
    28	        return Rect::new(area.x, area.y, 0, 0);
    29	    }
    30	    // panel bed
    31	    f.render_widget(
    32	        Block::default().style(Style::default().bg(theme::SLATE)),
    33	        area,
    34	    );
    35	    // NOTE: the panels no longer paint their own left light-edge / right shadow
    36	    // columns. Adjacent panes are separated by the dedicated `splitter()` rule
    37	    // drawn between them (app::draw); painting a per-panel edge PLUS a shadow
    38	    // PLUS the splitter stacked 2–3 vertical bars (▏▏▏) at every seam. The
    39	    // splitter is now the single, clean, theme::EDGE divider. The 1-col inner
    40	    // inset is kept as breathing room so pane content never abuts the seam.
    41	
    42	    let inner = Rect::new(
    43	        area.x + 1,
    44	        area.y,
    45	        area.width.saturating_sub(2),
    46	        area.height,
    47	    );
    48	
    49	    // ── title row: plain "TITLE" left, plain state text right ────────────────
    50	    // An empty title drops the label but keeps the row (state stays
    51	    // right-aligned, hairline stays) — used by the chat pane, where the app
    52	    // title bar + breadcrumb already say where you are and a third "OCEAN"
    53	    // was pure redundancy.
    54	    let title_fg = if focused { theme::BLUE } else { theme::COMMENT };
    55	    let state_txt = state.unwrap_or("");
    56	    let state_w = state_txt.chars().count();
    57	    let pad = (inner.width as usize).saturating_sub(title.chars().count() + 1 + state_w);
    58	    let mut spans = vec![Span::styled(
    59	        format!(" {title}"),
    60	        Style::default().fg(title_fg).add_modifier(Modifier::BOLD),
    61	    )];
    62	    spans.push(Span::raw(" ".repeat(pad)));
    63	    if !state_txt.is_empty() {
    64	        spans.push(Span::styled(
    65	            state_txt.to_string(),
    66	            Style::default().fg(theme::COMMENT),
    67	        ));
    68	    }
    69	    f.render_widget(
    70	        Paragraph::new(Line::from(spans)).style(Style::default().bg(theme::SLATE)),
    71	        Rect::new(inner.x, area.y, inner.width, 1),
    72	    );
    73	    // hairline underline
    74	    f.render_widget(
    75	        Paragraph::new(Line::from(Span::styled(
    76	            "─".repeat(inner.width as usize),
    77	            Style::default().fg(theme::BG_HL),
    78	        )))
    79	        .style(Style::default().bg(theme::SLATE)),
    80	        Rect::new(inner.x, area.y + 1, inner.width, 1),
    81	    );
    82	
    83	    Rect::new(
    84	        inner.x,
    85	        area.y + 2,
    86	        inner.width,
    87	        area.height.saturating_sub(3), // leave a footer row inside the bed
    88	    )
    89	}
