    20	/// Independently-clearable degraded state per health source. `Some(condition)`
    21	/// = degraded with that terse condition; `None` = healthy.
    22	#[derive(Debug, Clone, Default, PartialEq, Eq)]
    23	pub struct Health {
    24	    daemon: Option<String>,
    25	    sse: Option<String>,
    26	}
    27	
    28	impl Health {
    29	    /// Mark `source` degraded with `condition` (replaces the source's prior
    30	    /// condition; never touches the other source).
    31	    pub fn degrade(&mut self, source: HealthSource, condition: String) {
    32	        match source {
    33	            HealthSource::Daemon => self.daemon = Some(condition),
    34	            HealthSource::Sse => self.sse = Some(condition),
    35	        }
    36	    }
    37	
    38	    /// Mark `source` healthy. Clears ONLY that source — a daemon recovery must
    39	    /// not mask a still-degraded stream, and vice versa.
    40	    pub fn recover(&mut self, source: HealthSource) {
    41	        match source {
    42	            HealthSource::Daemon => self.daemon = None,
    43	            HealthSource::Sse => self.sse = None,
    44	        }
    45	    }
    46	
    47	    /// The effective degraded condition, if any. The daemon probe outranks the
    48	    /// SSE transport: a dead daemon explains a dead stream, so it reads first.
    49	    pub fn effective(&self) -> Option<&str> {
    50	        self.daemon.as_deref().or(self.sse.as_deref())
    51	    }
    52	}
