    83	/// Layout-safe text: newlines/tabs become spaces, remaining control chars are
    84	/// stripped. Daemon-fed strings (model ids, error bodies) are untrusted for
    85	/// layout and must never wrap or corrupt the single status row.
    86	fn sanitize(s: &str) -> String {
    87	    s.chars()
    88	        .map(|c| if c == '\n' || c == '\t' { ' ' } else { c })
    89	        .filter(|c| !c.is_control())
    90	        .collect()
    91	}
