    93	/// Everything the bottom row draws from, snapshotted once per frame.
    94	pub struct StatusData<'a> {
    95	    /// Model driving turns, if bound. Highest priority — never clipped.
    96	    pub model: Option<&'a str>,
    97	    /// Effective degraded health condition ([`Health::effective`]).
    98	    pub health: Option<&'a str>,
    99	    /// Unresolved error/notice message (empty/whitespace = nothing to show).
   100	    pub error: Option<&'a str>,
   101	    /// Live turn/tool activity, derived from chat state (`working` or the
   102	    /// current tool name). `None` when idle — never a stale copy.
   103	    pub activity: Option<&'a str>,
   104	    /// Cached git status; the branch renders whenever the workspace is a
   105	    /// repo, the counts (and Warn tone) only when nonzero.
   106	    pub git: Option<&'a git::Status>,
   107	    /// Last finished turn's tokens/sec, as the daemon reported it (provider
   108	    /// usage when available, daemon estimate otherwise). `None` = no reading.
   109	    pub tok_per_s: Option<f64>,
   110	}
