    91	/// Bottom footer row inside a panel drawn with [`draw`] — dim text on the bed.
    92	pub fn footer(f: &mut Frame, area: Rect, text: &str) {
    93	    if area.width < 6 || area.height < 4 {
    94	        return;
    95	    }
    96	    let inner_w = area.width.saturating_sub(2);
    97	    f.render_widget(
    98	        Paragraph::new(Span::styled(
    99	            pad_to(text, inner_w as usize),
   100	            Style::default().fg(theme::COMMENT),
   101	        ))
   102	        .style(Style::default().bg(theme::SLATE)),
   103	        Rect::new(area.x + 1, area.y + area.height - 1, inner_w, 1),
   104	    );
   105	}
