   107	pub fn fit_cells(s: &str, width: usize) -> String {
   108	    let mut out = String::new();
   109	    for grapheme in s.graphemes(true) {
   110	        let mut candidate = out.clone();
   111	        candidate.push_str(grapheme);
   112	        if UnicodeWidthStr::width(candidate.as_str()) > width {
   113	            break;
   114	        }
   115	        out = candidate;
   116	    }
   117	    out
   118	}
   119	
   120	pub fn pad_to(s: &str, w: usize) -> String {
   121	    let fitted = fit_cells(s, w);
   122	    let n = UnicodeWidthStr::width(fitted.as_str());
   123	    format!("{fitted}{}", " ".repeat(w.saturating_sub(n)))
   124	}
